import java.util.*;

public class Main {
    public static void main(String[] a) {
        Scanner sc = new Scanner(System.in);
        Map<String, String> tools = Map.of("experiment", "jshell", "bytecode", "javap",
                "dependencies", "jdeps", "runtime", "jlink", "installer", "jpackage");
        int n = sc.nextInt();
        List<String> goals = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            goals.add(sc.next());
        }
        int m = sc.nextInt();
        Set<String> written = new LinkedHashSet<>();
        for (int i = 0; i < m; i++) {
            written.add(sc.next());
        }

        Set<String> needed = new HashSet<>();          // 目的から導いた、要る道具
        boolean ready = true;
        for (String goal : goals) {
            String tool = tools.get(goal);
            needed.add(tool);
            if (written.contains(tool)) {
                System.out.println(goal + " " + tool);
            } else {
                System.out.println(goal + " " + tool + " MISSING");
                ready = false;
            }
        }
        Set<String> unused = new TreeSet<>();
        for (String tool : written) {
            if (!needed.contains(tool)) {
                unused.add(tool);
            }
        }
        for (String tool : unused) {
            System.out.println("UNUSED " + tool);
            ready = false;
        }
        System.out.println("ready=" + (ready ? "yes" : "no"));
    }
}

