import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int previewedIn = sc.nextInt();
        String standardText = sc.next();
        int standardIn = standardText.equals("-") ? Integer.MAX_VALUE
                : Integer.parseInt(standardText);
        int n = sc.nextInt();
        int usable = 0;
        for (int i = 0; i < n; i++) {
            String name = sc.next();
            int compileRelease = sc.nextInt();
            int runtimeRelease = sc.nextInt();
            String verdict;
            if (compileRelease < previewedIn) {
                verdict = "TOO_OLD";
            } else if (compileRelease >= standardIn) {
                verdict = "STANDARD";
            } else if (compileRelease == runtimeRelease) {
                verdict = "PREVIEW_OK";
            } else {
                verdict = "VERSION_MISMATCH";
            }
            if (verdict.equals("STANDARD") || verdict.equals("PREVIEW_OK")) {
                usable++;
            }
            System.out.println(name + " " + verdict);
        }
        System.out.println("usable=" + usable + "/" + n);
    }
}

