import java.util.*;

record Candidate(int version, String vendor, boolean lts) { }

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int minVersion = sc.nextInt(), n = sc.nextInt();
        List<Candidate> ok = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            int version = sc.nextInt();
            String vendor = sc.next();
            boolean supported = sc.next().equals("yes"), lts = sc.next().equals("yes");
            if (supported && version >= minVersion) ok.add(new Candidate(version, vendor, lts));
        }
        ok.sort(Comparator.comparingInt(Candidate::version).reversed().thenComparing(Candidate::vendor));
        if (ok.isEmpty()) System.out.println("NONE");
        else for (Candidate c : ok) System.out.println(c.version() + " " + c.vendor() + " " + (c.lts() ? "LTS" : "-"));
        List<Candidate> pool = new ArrayList<>();
        for (Candidate c : ok) if (c.lts()) pool.add(c);
        if (pool.isEmpty()) pool = ok;
        System.out.println(pool.isEmpty() ? "PICK NONE" : "PICK " + pool.get(0).version() + " " + pool.get(0).vendor());
    }
}

