import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.nextLine().trim());
        List<String[]> apis = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            apis.add(sc.nextLine().trim().split("\\s+"));
        }

        apis.sort(Comparator.comparingInt((String[] row) -> weight(row[1]))
                .thenComparing(row -> -Integer.parseInt(row[2]))
                .thenComparing(row -> row[0]));

        int now = 0;
        int planned = 0;
        for (String[] row : apis) {
            int uses = Integer.parseInt(row[2]);
            if (row[1].equals("removed")) {
                now += uses;
            } else if (row[1].equals("for-removal")) {
                planned += uses;
            }
            System.out.println(row[0] + " " + row[1] + " " + uses);
        }
        System.out.println("今すぐ " + now);
        System.out.println("期限あり " + planned);
        System.out.println("判定 " + (hasRemoved(apis) ? "ビルド不可" : "計画的移行"));
    }

    /** 重さを小さい数で表す。小さいほど先に直す。 */
    static int weight(String state) {
        return switch (state) {
            case "removed" -> 0;
            case "for-removal" -> 1;
            default -> 2;
        };
    }

    /** 使用箇所が0件でも、removed が並んでいればビルドは通らない。 */
    static boolean hasRemoved(List<String[]> apis) {
        for (String[] row : apis) {
            if (row[1].equals("removed")) {
                return true;
            }
        }
        return false;
    }
}
